#include <stdio.h>
/*
 * ex03：数据冒险（RAW）检测 —— 旁路能救 ALU 结果，救不了 load-use
 * 规则（五段流水线 IF/ID/EX/MEM/WB）：
 *   - 前一条是 ALU 指令：结果在 EX 末就算出来，后一条的 EX 正好需要 → 旁路转发，0 停顿；
 *   - 前一条是 LW：数据要到 MEM 末才拿到，后一条 EX 已经开始 → 必须插 1 拍 stall；
 *   - 相隔 >=2 条指令：写回已完成，无需处理。
 * 本程序顺序扫描指令对，判定冒险类型并累计停顿。
 */
typedef struct {
    const char *name;  /* 助记符 */
    int is_load;       /* 是否 load（决定是 1 拍还是 0 拍） */
    int dst;           /* 写的目的寄存器，0 表示不写 */
    int src1, src2;    /* 两个源寄存器 */
} Insn;

int main(void) {
    Insn prog[] = {
        {"ADD R1,R2,R3", 0, 1, 2, 3},   /* 写 R1 */
        {"SUB R4,R1,R5", 0, 4, 1, 5},   /* 读 R1：RAW，ALU 旁路可解 */
        {"LW  R6,0(R4)", 1, 6, 4, 0},   /* 读 R4：RAW，ALU 旁路可解；写 R6 且是 load */
        {"SW  0(R6),R1", 0, 0, 6, 1},   /* 读 R6：load-use，必须停 1 拍 */
        {"ADD R7,R6,R4", 0, 7, 6, 4},
    };
    int n = (int)(sizeof(prog) / sizeof(prog[0]));
    int total_stall = 0;

    printf("数据冒险(RAW)检测：旁路转发能消 EX->EX，load-use 仍需 1 拍\n");
    for (int i = 0; i < n - 1; i++) {
        /* 后一条的任一源寄存器 == 前一条的目的寄存器，就是 RAW 冒险 */
        int hazard = (prog[i].dst != 0) &&
                     (prog[i].dst == prog[i + 1].src1 || prog[i].dst == prog[i + 1].src2);
        if (hazard) {
            int st = prog[i].is_load ? 1 : 0;   /* 只有 load-use 才真的停 */
            total_stall += st;
            printf("[%d->%d] %s 写R%d, %s 读R%d : RAW冒险, %s\n",
                   i, i + 1, prog[i].name, prog[i].dst,
                   prog[i + 1].name, prog[i].dst,
                   st ? "LOAD-USE 插1拍stall" : "ALU旁路 0停顿");
        }
    }
    printf("共检测RAW冒险导致停顿=%d 拍\n", total_stall);
    return 0;
}
